import{cycleState,ivfStage}from './repro-models.js?v=20261023-physicscomplete01';
export function buildRepro(g,T,w={}){const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.3}),ball=(p,s,c,name)=>{let m=new T.Mesh(new T.SphereGeometry(1,32,24),mat(c));m.position.set(...p);m.scale.set(...s);m.name=name;g.add(m);},tube=(pts,r,c,name)=>{let m=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(pts.map(p=>new T.Vector3(...p))),48,r,12,false),mat(c));m.name=name;g.add(m);};let p=w.progress??.5;
if(w.kind==='puberty'){for(let side of[-1,1]){ball([side*1.2,0,0],[.5,.35,.35],0xc69d94,side<0?'ovarian-source':'testicular-source');let m=new T.Mesh(new T.OctahedronGeometry(.12),mat(0xa8cbd0));m.position.set(side*.5,.3,.3);m.name='hormone-signal';g.add(m);}return;}
if(w.kind==='ivf'){let dish=new T.Mesh(new T.CylinderGeometry(1.7,1.5,.12,64),new T.MeshStandardMaterial({color:0xa5c8d0,roughness:.2,transparent:true,opacity:.35}));dish.name='culture-dish';g.add(dish);for(let j=0;j<3;j++){let n=ivfStage(p)>=3?8:1;for(let i=0;i<n;i++)ball([-.9+j*.9+Math.cos(i*Math.PI/4)*.1,.18,Math.sin(i*Math.PI/4)*.1],[n===1?.2:.07,n===1?.2:.07,n===1?.2:.07],0xe6c69d,n===1?'egg':'embryo-cell');}return;}
let f=cycleState(p);tube([[-1.4,.55,0],[-.8,.85,0],[-.55,.35,0],[0,-.8,0],[.55,.35,0],[.8,.85,0],[1.4,.55,0]],.14,0xc89c96,'uterus-outline');tube([[-.45,.3,.1],[0,-.5,.1],[.45,.3,.1]],f.lining*.01,0xe2b49d,'uterus-lining');ball([-1.65,.45,0],[.38,.25,.3],0xb58b83,'ovary');ball([f.eggReleased?-1.1:-1.65,.5,.15],[.1,.1,.1],0xe6c69d,'egg');}
